#include <cstdint>
#include <cstring>
#include <bit>

#pragma pack(push, 1)
struct MsgHeader { uint16_t len; uint8_t type; uint64_t seq; };  // wire layout
struct AddOrder  { uint64_t order_id; uint8_t side; uint32_t qty; int32_t price; };
#pragma pack(pop)

struct NormEvent { enum K{ADD,CANCEL,TRADE} kind; int32_t price; uint32_t qty; uint8_t side; };

class FeedHandler {
public:
    // Parse one packet (may contain multiple messages) directly in the buffer.
    template <class Sink>
    void on_packet(const uint8_t* p, size_t n, Sink&& emit) {
        size_t off = 0;
        while (off + sizeof(MsgHeader) <= n) {
            const auto* h = reinterpret_cast<const MsgHeader*>(p + off);
            uint64_t seq = le(h->seq);
            if (seq != expected_) { handle_gap(seq); /* may enter recovery */ }
            else { dispatch(h, p + off + sizeof(MsgHeader), emit); ++expected_; }
            off += le(h->len);
        }
    }
private:
    static uint16_t le(uint16_t v){ return v; }   // assume host==wire endianness here
    static uint64_t le(uint64_t v){ return v; }

    template <class Sink>
    void dispatch(const MsgHeader* h, const uint8_t* body, Sink&& emit) {
        switch (h->type) {
            case 'A': { const auto* a = reinterpret_cast<const AddOrder*>(body);
                        emit(NormEvent{NormEvent::ADD, le32(a->price), a->qty, a->side}); break; }
            // case 'X': cancel ... case 'P': trade ...
            default: break;   // skip message types we don't need (lazy decode)
        }
    }
    static int32_t le32(int32_t v){ return v; }
    void handle_gap(uint64_t) { /* A/B already deduped upstream; else snapshot/retransmit */ }
    uint64_t expected_ = 0;
};

#include <cstdint>

// Deduplicate two identical feeds by sequence: act on the first arrival.
class AbArbiter {
public:
    // returns true if this seq is new (caller should process it)
    bool accept(uint64_t seq) {
        if (seq < next_) return false;          // old/duplicate
        if (seq == next_) { ++next_; advance_over_buffered(); return true; }
        buffered_[seq & MASK] = true;           // ahead: remember, gap pending
        return false;
    }
private:
    void advance_over_buffered() {              // fill in any now-contiguous seqs
        while (buffered_[next_ & MASK]) { buffered_[next_ & MASK] = false; ++next_; }
    }
    static constexpr uint64_t MASK = (1 << 20) - 1;
    bool buffered_[1 << 20] = {};
    uint64_t next_ = 0;
};
// With A/B, most 'gaps' on one feed are instantly filled by the other -> rare true recovery.
